package com.edunexa.app
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Color
import android.graphics.pdf.PdfDocument
import android.graphics.pdf.PdfRenderer
import android.net.Uri
import android.os.Bundle
import android.os.ParcelFileDescriptor
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AlertDialog
import com.edunexa.app.tools.SafeImages
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader
import com.tom_roush.pdfbox.multipdf.PDFMergerUtility
import com.tom_roush.pdfbox.pdmodel.PDDocument
import java.io.File
import java.util.concurrent.Executors
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

class PdfToolkitActivity:EduActivity(){
 private lateinit var status:TextView;private lateinit var preview:ImageView;private lateinit var save:Button;private var pending:File?=null;private var busy=false;private var operation="";private val executor=Executors.newSingleThreadExecutor()
 private fun temp(ext:String)=File.createTempFile("edunexa_",ext,cacheDir)
 private val imagePicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)runTask{val b=SafeImages.decode(this,uri,1600);val out=temp(".pdf");PdfDocument().use{doc->val p=doc.startPage(PdfDocument.PageInfo.Builder(b.width,b.height,1).create());p.canvas.drawBitmap(b,0f,0f,null);doc.finishPage(p);out.outputStream().use{doc.writeTo(it)}};out to b}}
 private val pdfPicker=registerForActivityResult(ActivityResultContracts.OpenMultipleDocuments()){uris->if(uris.isNotEmpty()){if(operation=="merge")runTask{require(uris.size in 2..20){"Choose 2–20 PDFs"};val merger=PDFMergerUtility();val inputs=uris.map{copy(it)};require(inputs.sumOf{it.length()}<=40L*1024*1024){"Use less than 40 MB of PDFs"};inputs.forEach{merger.addSource(it)};val out=temp(".pdf");merger.destinationFileName=out.path;merger.mergeDocuments(null);out to null}else if(operation=="split"||operation=="reorder"){val field=EditText(this).apply{hint="Pages, e.g. 1-3,5 or 3,1,2"};AlertDialog.Builder(this).setTitle("Select page order").setView(field).setNegativeButton("Cancel",null).setPositiveButton("Process"){_,_->val spec=field.text.toString();runTask{PDDocument.load(copy(uris[0])).use{src->val pages=parsePages(spec,src.numberOfPages);require(pages.isNotEmpty()){ "Choose valid pages" };val out=temp(".pdf");PDDocument().use{doc->pages.forEach{doc.importPage(src.getPage(it))};doc.save(out)};out to null}}}.show()}else runTask{render(uris[0],operation=="images")}}}
 private val saver=registerForActivityResult(ActivityResultContracts.StartActivityForResult()){result->val uri=result.data?.data;val file=pending;if(result.resultCode==RESULT_OK&&uri!=null&&file!=null)runTask{contentResolver.openOutputStream(uri)?.use{output->file.inputStream().use{it.copyTo(output)}}?:error("Could not write output");file to null}}
 override fun onCreate(state:Bundle?){super.onCreate(state);PDFBoxResourceLoader.init(applicationContext);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,24,28,28)};setContentView(ScrollView(this).apply{addView(root)});root.addView(TextView(this).apply{text="PDF Toolkit";textSize=27f;setTypeface(typeface,android.graphics.Typeface.BOLD)});root.addView(TextView(this).apply{text="Files up to 20 MB each • up to 100 rendered pages. Review the output before saving."});fun action(label:String,op:String){root.addView(Button(this).apply{text=label;setOnClickListener{if(busy)return@setOnClickListener;operation=op;if(op=="image")imagePicker.launch(arrayOf("image/*"))else pdfPicker.launch(arrayOf("application/pdf"))}})};action("JPG / Image → PDF","image");action("Merge PDFs","merge");action("Split PDF","split");action("Reorder / Remove Pages","reorder");action("PDF → Images ZIP","images");action("Create Flattened Sharing PDF","flatten");status=TextView(this);root.addView(status);preview=ImageView(this).apply{adjustViewBounds=true};root.addView(preview,LinearLayout.LayoutParams(-1,450));save=Button(this).apply{text="Save Output";isEnabled=false;setOnClickListener{if(busy)return@setOnClickListener;val f=pending?:return@setOnClickListener;saver.launch(Intent(Intent.ACTION_CREATE_DOCUMENT).apply{type=if(f.extension=="zip")"application/zip" else "application/pdf";putExtra(Intent.EXTRA_TITLE,"EduNexa_Output.${f.extension}");addCategory(Intent.CATEGORY_OPENABLE)})}};root.addView(save)}
 private fun runTask(block:()->Pair<File,Bitmap?>){if(busy)return;busy=true;save.isEnabled=false;status.text="Processing…";executor.execute{runCatching(block).onSuccess{(file,bmp)->runOnUiThread{if(!isDestroyed){pending=file;bmp?.let{preview.setImageBitmap(it)};status.text="Output ready • ${file.length()/1024} KB";save.isEnabled=true;busy=false}else bmp?.recycle()}}.onFailure{e->runOnUiThread{if(!isDestroyed){status.text=e.message?:"Could not process file";busy=false;save.isEnabled=pending!=null}}}}}
 private fun copy(uri:Uri):File{val out=temp(".pdf");contentResolver.openInputStream(uri)?.use{input->out.outputStream().use{output->val buffer=ByteArray(8192);var total=0L;while(true){val n=input.read(buffer);if(n<0)break;total+=n;require(total<=20L*1024*1024){"Choose a PDF below 20 MB"};output.write(buffer,0,n)}}}?:error("Could not read file");return out}
 private fun parsePages(spec:String,max:Int):List<Int>{val out=mutableListOf<Int>();for(part in spec.split(',').map{it.trim()}){if('-' in part){val a=part.substringBefore('-').toIntOrNull()?:error("Invalid page range");val b=part.substringAfter('-').toIntOrNull()?:error("Invalid page range");require(a in 1..max&&b in a..max&&b-a<100){"Invalid page range"};out.addAll((a..b).map{it-1})}else{val n=part.toIntOrNull()?:error("Enter page numbers");require(n in 1..max){"Page does not exist"};out.add(n-1)}};require(out.size<=100){"Choose up to 100 pages"};return out}
 private fun render(uri:Uri,zip:Boolean):Pair<File,Bitmap?>{val src=copy(uri);val out=temp(if(zip)".zip" else ".pdf");var first:Bitmap?=null;PdfRenderer(ParcelFileDescriptor.open(src,ParcelFileDescriptor.MODE_READ_ONLY)).use{renderer->require(renderer.pageCount in 1..100){"Use a PDF with up to 100 pages"};val pdf=if(zip)null else PdfDocument();val archive=if(zip)ZipOutputStream(out.outputStream())else null;try{for(i in 0 until renderer.pageCount){check(!Thread.currentThread().isInterrupted){"Processing cancelled"};renderer.openPage(i).use{p->val scale=minOf(1f,1240f/maxOf(p.width,p.height));val w=maxOf(1,(p.width*scale).toInt());val h=maxOf(1,(p.height*scale).toInt());val b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);if(i==0)first=b.copy(Bitmap.Config.ARGB_8888,false);if(archive!=null){archive.putNextEntry(ZipEntry("page_${i+1}.jpg"));b.compress(Bitmap.CompressFormat.JPEG,85,archive);archive.closeEntry()}else if(pdf!=null){val page=pdf.startPage(PdfDocument.PageInfo.Builder(w,h,i+1).create());page.canvas.drawBitmap(b,0f,0f,null);pdf.finishPage(page)};b.recycle()}};pdf?.let{out.outputStream().use{stream->it.writeTo(stream)}}}finally{archive?.close();pdf?.close()}};return out to first}
 override fun onDestroy(){executor.shutdownNow();super.onDestroy()}
}
